-- EraLens period import: commercial-events
-- Window: -138-01 .. 1911-12
BEGIN;

-- cleanup
DELETE FROM event_dynasties WHERE event_id = 'commerce-treaty-of-nanking-five-ports';
DELETE FROM events WHERE id = 'commerce-treaty-of-nanking-five-ports';
DELETE FROM events WHERE id IN ('commerce-cucumber-recorded-in-qimin-yaoshu', 'commerce-maize-earliest-record', 'commerce-chili-earliest-record', 'commerce-tomato-recorded-in-zhipin', 'commerce-tobacco-recorded-in-jingyue-quanshu');
DELETE FROM event_dynasties WHERE event_id IN ('commerce-cucumber-introduction', 'commerce-maize-introduction', 'commerce-sweet-potato-introduction', 'commerce-chili-introduction', 'commerce-tomato-introduction', 'commerce-tobacco-introduction');

-- persons

-- dynasties

-- reigns

-- events
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-cucumber-introduction', '黄瓜传入中原', 'agriculture', 'point', 'year', TRUE, '传统记述将黄瓜（胡瓜）与张骞通西域相联系。按其前138年首次出使作为最早叙述时点；此为传播叙事的年代锚点，不能证明黄瓜确切引种年。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '黄瓜又称胡瓜，原产地及具体首传路线仍有不同说法。传统记述将其与张骞通西域联系起来；北魏《齐民要术》已记载栽培方法，证明当时已在中国种植。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-maize-introduction', '玉米传入中国', 'agriculture', 'point', 'year', TRUE, '1534年《巩县志》有“玉麦”记载，是目前常见的中国早期文献记录之一；以该最早记载年作单点，不等同于实际首次传入年。', 1534, 12, 18419, NULL, NULL, NULL, NULL, NULL, NULL, '玉米原产美洲，明代经海路及可能的陆路传入中国。1534年《巩县志》所见“玉麦”是早期记载之一；其耐旱、适应性强，后来在山地和旱地广泛种植。具体首传地点与路线尚有争议。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-sweet-potato-introduction', '甘薯经海路传入福建', 'agriculture', 'point', 'year', TRUE, '福建引种记载有万历十年（1582）、万历十一至十二年及万历二十一年（1593）等说法；按要求取最早提及的1582年，保留不同记载的分歧。', 1582, 12, 18995, NULL, NULL, NULL, NULL, NULL, NULL, '甘薯原产美洲，经海上贸易网络传入福建。关于陈益、陈振龙等人的引种时间和路线，地方记载并不一致；甘薯耐瘠、高产，后来成为重要的粮食补充和救荒作物。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-chili-introduction', '辣椒传入中国', 'agriculture', 'point', 'year', TRUE, '具体首传路线和年份未定；现有研究常置于16世纪后期至17世纪前期。按截图所列范围取最早年份1570作单点，表示最早提及的年代而非确切传入年。', 1570, 12, 18851, NULL, NULL, NULL, NULL, NULL, NULL, '辣椒原产美洲，随跨洋贸易传入亚洲并进入中国。早期多作观赏或药用植物，之后逐渐进入饮食，在各地形成不同的食用习惯。中国首传的路线和年份尚不能确考。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-tomato-introduction', '番茄传入中国', 'agriculture', 'point', 'year', TRUE, '中国首传时间难以确考；1617年周文华《汝南圃史·植品》被用作番茄在华早期名称记载。按该最早文献线索取单点，不视为实际引种年。', 1617, 12, 19415, NULL, NULL, NULL, NULL, NULL, NULL, '番茄原产美洲，随海上贸易传播至亚洲并传入中国。中国首传时间和路线未能确证；明代文献中的相关名称提供了早期在华线索，番茄初期较为稀见，后来才普遍成为食用蔬菜。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-tobacco-introduction', '烟草传入中国', 'agriculture', 'point', 'year', TRUE, '烟草传入时间有16至17世纪等说；按资料提及的最早年份1540作单点。1624年《景岳全书》回述万历年间闽、广已有烟草，均不能据此断定准确首传年。', 1540, 12, 18491, NULL, NULL, NULL, NULL, NULL, NULL, '烟草原产美洲，经菲律宾吕宋及海上贸易网络传入中国，随后由东南沿海向内地传播。早期兼作药用，后来成为广泛种植和消费的经济作物。具体首传年份仍有争议。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-song-guangzhou-shipping-office', '广州设市舶司', 'commerce', 'point', 'year', FALSE, '开宝四年（971）；广州博物馆所藏北宋《大宋新修广利王庙之碑》记载平南汉后设司。', 971, 12, 11663, NULL, NULL, NULL, NULL, NULL, NULL, '北宋平定南汉后在广州设置市舶司，专门管理海外商船、蕃货和贸易事务。此后宋廷陆续在东南沿海增设机构，海贸成为国家财政与跨区域交流的重要组成。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-song-tea-horse-trade', '茶马互市兴起', 'commerce', 'point', 'year', FALSE, '熙宁七年（1074）被视为宋代茶马制度形成的重要年份；贸易实践和机构调整持续多年。', 1074, 12, 12899, NULL, NULL, NULL, NULL, NULL, NULL, '宋廷在四川等地设置茶马贸易机构，以茶换取西北及西南地区所需战马，并以官府专營、茶引等方式管理交易。茶马互市把边疆贸易、軍需供给与区域治理联系起来。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-longqing-yuegang-opening', '隆庆开海', 'commerce', 'point', 'year', FALSE, '隆庆元年（1567）；采用海澄县志等记载的开港年份。', 1567, 12, 18815, NULL, NULL, NULL, NULL, NULL, NULL, '明廷在福建月港有限度开放民间海上贸易，商船可依规出洋，月港成为东南沿海重要贸易港。政策并未废除海禁，走私、朝贡贸易与许可贸易仍交织并存。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-qing-maritime-trade-reopened', '清廷开海', 'commerce', 'point', 'year', FALSE, '康熙二十三年（1684）解除海禁、设置海关；开放港口的诏令及实施在1685年，事件以政策转折年定位。', 1684, 12, 20219, NULL, NULL, NULL, NULL, NULL, NULL, '平定台湾后，清廷解除海禁并设粤、闽、浙、江四海关管理海上贸易与征税；次年开放广州、漳州、宁波、云台山等贸易港。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-qing-canton-system', '广州一口通商', 'commerce', 'point', 'year', FALSE, '乾隆二十二年（1757）政策转折；各口岸执行和限制逐渐落实，不将其解释为所有对外贸易一概中止。', 1757, 12, 21095, NULL, NULL, NULL, NULL, NULL, NULL, '清廷将西洋商船贸易集中于广州，外商主要通过广州行商体系交易。广州由此成为清代中西贸易的核心口岸，这一格局延续至鸦片战争前后。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-grape-introduction', '葡萄经西域传入', 'agriculture', 'point', 'year', TRUE, '《汉书·西域传》记汉使引入蒲陶并种于离宫馆旁；按张骞前138年首次出使作最早记述锚点，不将其视为确切引种年份。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '葡萄原生种早已见于中国文献；张骞通西域后，从大宛引入适于酿酒的栽培品种，在长安一带推广。汉代以后葡萄栽培和酿酒逐渐发展。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-pomegranate-introduction', '石榴传入中国', 'agriculture', 'point', 'year', TRUE, '截图将石榴列为西汉张骞通西域传入；用前138年作为所述传播时期的最早年份。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '石榴原产西亚，经西域交通传入中国，汉代已进入宫苑和园圃栽培。石榴后来成为常见果树，也形成多子寓意。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-walnut-introduction', '核桃（胡桃）传入中国', 'agriculture', 'point', 'year', TRUE, '截图标注西汉、张骞带回；以张骞前138年首次出使作为最早叙述时点，传统归因不等于已证实的单次引种。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '核桃又称胡桃，传统记述将其由西域传入与张骞出使相联系。它作为坚果和木本油料逐步在中国栽培。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-fig-introduction', '无花果传入中国', 'agriculture', 'point', 'year', TRUE, '截图记为魏晋南北朝（一说唐代盛行）；取该时期起始年220年作最早提及的年代锚点，不作为确切引种年。', 220, 12, 2651, NULL, NULL, NULL, NULL, NULL, NULL, '无花果原产西亚，魏晋南北朝时期已在中国传播；后世文献和园艺栽培记载逐渐增多。具体最初传入时间仍有不同说法。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
