INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-sesame-introduction', '芝麻（胡麻）传入中国', 'agriculture', 'point', 'year', TRUE, '农业史研究认为汉代从西域传入芝麻；截图联系张骞通西域，按前138年作为最早叙述时点。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '芝麻古称胡麻，汉代由西域传入后成为重要油料和食用作物，推动了植物油加工与食用的发展。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-alfalfa-introduction', '苜蓿传入中国', 'agriculture', 'point', 'year', TRUE, '《史记》《汉书》记载汉武帝时自大宛引苜蓿；按张骞前138年首次出使作为最早传播叙述锚点。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '苜蓿原产西亚，汉代自大宛引种，先为宫苑试种，后推广到西北农牧交错地区，成为重要饲草，也可作绿肥和蔬菜。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-pepper-introduction', '胡椒传入中国', 'agriculture', 'point', 'year', TRUE, '截图列为汉代西域交流时期输入；以张骞前138年首次出使作为最早提及的年代锚点，胡椒具体首传路线仍有争议。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '胡椒原产南亚及东南亚，经跨区域贸易进入中国，早期作为珍贵香料和药材流通。其在中国的广泛使用晚于最初传入。', NULL, NULL, NULL)
