INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-pea-introduction', '豌豆（胡豆）传入中国', 'agriculture', 'point', 'year', TRUE, '截图列为西汉由西亚、地中海地区传入；按西汉西域交流起点前138年落点。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '豌豆又称胡豆，属西亚来源作物，汉代经西域交流传入后逐步成为粮食、蔬菜兼用豆类。', NULL, NULL, NULL)
