INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-cowpea-introduction', '豇豆（胡豆）传入中国', 'agriculture', 'point', 'year', TRUE, '截图列为西汉豆类引入；按最早提及的西汉西域交流时点前138年落年。古代“胡豆”名称所指作物并非始终一致。', -138, 12, -1633, NULL, NULL, NULL, NULL, NULL, NULL, '豇豆古称胡豆之一，传统农史将其列入汉唐间由域外传入的园艺作物，后来广泛用于鲜食和豆类生产。', NULL, NULL, NULL)
