INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-peanut-introduction', '花生传入中国', 'agriculture', 'point', 'year', TRUE, '截图将花生列在明代中后期，并提及16世纪初经东南亚传播；取1500年作为其所述范围的最早年份，不视为确切首传年。', 1500, 12, 18011, NULL, NULL, NULL, NULL, NULL, NULL, '花生原产南美洲，明代经海路进入中国，随后逐渐成为重要油料和食用作物。早期引种路线与时间仍有不同说法。', NULL, NULL, NULL)
