INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-pumpkin-introduction', '南瓜传入中国', 'agriculture', 'point', 'year', TRUE, '截图列为明代美洲作物；按明代时期最早年份1368年无法证明具体引种，依其明代中后期传播叙述取1500年作最早年代锚点。', 1500, 12, 18011, NULL, NULL, NULL, NULL, NULL, NULL, '南瓜原产美洲，随跨洋贸易在明代传入中国，因适应性较强而传播到多地，成为蔬菜和粮食补充。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-sunflower-introduction', '向日葵传入中国', 'agriculture', 'point', 'year', TRUE, '截图将向日葵列在美洲作物输入潮中，未给出确切年份；按明清之际最早阶段取1600年作近似单点。', 1600, 12, 19211, NULL, NULL, NULL, NULL, NULL, NULL, '向日葵原产北美洲，明清之际经跨洋贸易传入中国，后逐渐发展为观赏、食用和油料作物。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, is_approximate = EXCLUDED.is_approximate, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-cashew-introduction', '腰果传入中国', 'agriculture', 'point', 'year', TRUE, '截图列入明清美洲作物，未给出确年；以明清之际1600年作为所述时期最早年份，表示年代框架而非确切引种年。', 1600, 12, 19211, NULL, NULL, NULL, NULL, NULL, NULL, '腰果原产美洲热带地区，随海上贸易传播至亚洲；在中国的引种和规模化栽培较晚，主要适应南方热带地区。', NULL, NULL, NULL)
