INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('agri-pineapple-introduction', '菠萝（凤梨）传入中国', 'agriculture', 'point', 'year', TRUE, '截图列为明末由南美传入；按“明末”这一时期的最早年份取1600年作为单点，实际首传年未详。', 1600, 12, 19211, NULL, NULL, NULL, NULL, NULL, NULL, '菠萝原产南美洲热带地区，经海路传入亚洲并进入中国南方。此后在岭南、台湾等地逐步栽培。', NULL, NULL, NULL)
